import json
d=json.load(open('/tmp/s.json'))['data']
G={}
for i,row in enumerate(d['board']):
    r=8-i
    for j,ch in enumerate(row): G[(j,r)]=ch
def nm(s): return chr(97+s[0])+str(s[1])
def flips(g,s,me):
    c,r=s; opp='W' if me=='B' else 'B'; out=[]
    for dc in(-1,0,1):
        for dr in(-1,0,1):
            if dc==0==dr: continue
            line=[];cc=c+dc;rr=r+dr
            while 0<=cc<8 and 1<=rr<=8 and g.get((cc,rr))==opp:
                line.append((cc,rr));cc+=dc;rr+=dr
            if line and 0<=cc<8 and 1<=rr<=8 and g.get((cc,rr))==me: out+=line
    return out
def legal(g,me):
    return {s:flips(g,s,me) for s in g if g[s]=='.' and flips(g,s,me)}
def walk(g,who,passed,path):
    L=legal(g,who)
    if not L:
        if passed: 
            b=sum(1 for v in g.values() if v=='B')
            print(' '.join(path), '=> B',b,'W',64-b-sum(1 for v in g.values() if v=='.'))
            return
        walk(g,'W' if who=='B' else 'B',True,path+['(pass)'])
        return
    for s,f in sorted(L.items()):
        g2=dict(g); g2[s]=who
        for x in f: g2[x]=who
        walk(g2,'W' if who=='B' else 'B',False,path+[who+nm(s)])
